import{_ as c,r as e,o as l,c as i,e as t,a as s,s as r,d as a}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Response & View - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Basic Responses","slug":"basic-responses","link":"#basic-responses","children":[{"level":4,"title":"Returning strings from a CMS method","slug":"returning-strings-from-a-cms-method","link":"#returning-strings-from-a-cms-method","children":[]},{"level":4,"title":"Returning strings from AJAX handlers","slug":"returning-strings-from-ajax-handlers","link":"#returning-strings-from-ajax-handlers","children":[]},{"level":4,"title":"Returning strings from routes","slug":"returning-strings-from-routes","link":"#returning-strings-from-routes","children":[]},{"level":4,"title":"Creating custom responses","slug":"creating-custom-responses","link":"#creating-custom-responses","children":[]},{"level":3,"title":"Attaching Headers to Responses","slug":"attaching-headers-to-responses","link":"#attaching-headers-to-responses","children":[]},{"level":3,"title":"Attaching Cookies to Responses","slug":"attaching-cookies-to-responses","link":"#attaching-cookies-to-responses","children":[]}]},{"level":2,"title":"Other Response Types","slug":"other-response-types","link":"#other-response-types","children":[{"level":3,"title":"View Responses","slug":"view-responses","link":"#view-responses","children":[]},{"level":3,"title":"JSON Responses","slug":"json-responses","link":"#json-responses","children":[]},{"level":3,"title":"File Downloads","slug":"file-downloads","link":"#file-downloads","children":[{"level":4,"title":"Streamed Downloads","slug":"streamed-downloads","link":"#streamed-downloads","children":[]}]},{"level":3,"title":"File Responses","slug":"file-responses","link":"#file-responses","children":[]}]},{"level":2,"title":"Redirects","slug":"redirects","link":"#redirects","children":[{"level":3,"title":"Returning a Redirect with Flash Data","slug":"returning-a-redirect-with-flash-data","link":"#returning-a-redirect-with-flash-data","children":[{"level":4,"title":"Redirecting to the Previous URL","slug":"redirecting-to-the-previous-url","link":"#redirecting-to-the-previous-url","children":[]},{"level":4,"title":"Redirecting to the Current Page","slug":"redirecting-to-the-current-page","link":"#redirecting-to-the-current-page","children":[]}]}]},{"level":2,"title":"Response Macros","slug":"response-macros","link":"#response-macros","children":[]},{"level":2,"title":"Views","slug":"views","link":"#views","children":[{"level":4,"title":"Passing Data to Views","slug":"passing-data-to-views","link":"#passing-data-to-views","children":[]},{"level":4,"title":"Passing a Sub-view to a View","slug":"passing-a-sub-view-to-a-view","link":"#passing-a-sub-view-to-a-view","children":[]},{"level":4,"title":"Determining If a View Exists","slug":"determining-if-a-view-exists","link":"#determining-if-a-view-exists","children":[]},{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/extend/services/response-view.md","filePath":"3.x/extend/services/response-view.md"}'),u={name:"3.x/extend/services/response-view.md"};function d(k,n,g,h,m,v){const o=e("pre-heading"),p=e("post-heading");return l(),i("div",null,[t(o),n[0]||(n[0]=s("h1",null,"Response & View",-1)),t(p),n[1]||(n[1]=r(`<h2 id="basic-responses"><a href="#basic-responses" class="header-anchor">#</a> Basic Responses</h2><p>A response can be returned from almost PHP method that is used by the page. This includes all the CMS methods contained in the <a href="./../../cms/themes/layouts.html">Layout Execution Life Cycle</a> and <a href="./../../cms/ajax/handlers.html">AJAX handler definitions</a>.</p><h4 id="returning-strings-from-a-cms-method"><a href="#returning-strings-from-a-cms-method" class="header-anchor">#</a> Returning strings from a CMS method</h4><p>Returning a string from a CMS page, layout or component method will halt the process at this point and override the default behavior, so here it will display the &quot;Hello World&quot; string instead of displaying the page.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="returning-strings-from-ajax-handlers"><a href="#returning-strings-from-ajax-handlers" class="header-anchor">#</a> Returning strings from AJAX handlers</h4><p>Returning a string from an AJAX handler will add the string to the response collection using the default key of <code>result</code>. Requested partials will still be included in the response.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
    <span class="token comment">// [&#39;result&#39; =&gt; &#39;Hello World&#39;]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="returning-strings-from-routes"><a href="#returning-strings-from-routes" class="header-anchor">#</a> Returning strings from routes</h4><p>Returning a string from a <a href="./../system/routing.html">route definition</a> will act the same as a CMS method and display the string as the response.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="creating-custom-responses"><a href="#creating-custom-responses" class="header-anchor">#</a> Creating custom responses</h4><p>For a more robust solution, returning a <code>Response</code> object providing a variety of methods for building HTTP responses. We will explore this topic further in this article.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$contents</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Page not found&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$statusCode</span> <span class="token operator">=</span> <span class="token number">404</span><span class="token punctuation">;</span>
<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$contents</span><span class="token punctuation">,</span> <span class="token variable">$statusCode</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="attaching-headers-to-responses"><a href="#attaching-headers-to-responses" class="header-anchor">#</a> Attaching Headers to Responses</h3><p>Keep in mind that most response methods are chainable, allowing for the fluent building of responses. For example, you may use the <code>header</code> method to add a series of headers to the response before sending it back to the user:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-One&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;X-Header-Two&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Header Value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>A practical example of this could be returning an XML response:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$xmlString</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="attaching-cookies-to-responses"><a href="#attaching-cookies-to-responses" class="header-anchor">#</a> Attaching Cookies to Responses</h3><p>The <code>withCookie</code> method allows you to easily attach cookies to the response. For example, you may use the withCookie method to generate a cookie and attach it to the response instance:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>withCookie</code> method accepts additional optional arguments which allow you to further customize your cookie&#39;s properties:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">-&gt;</span><span class="token function">withCookie</span><span class="token punctuation">(</span><span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$minutes</span><span class="token punctuation">,</span> <span class="token variable">$path</span><span class="token punctuation">,</span> <span class="token variable">$domain</span><span class="token punctuation">,</span> <span class="token variable">$secure</span><span class="token punctuation">,</span> <span class="token variable">$httpOnly</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="other-response-types"><a href="#other-response-types" class="header-anchor">#</a> Other Response Types</h2><p>The <code>Response</code> facade may be used to conveniently generate other types of response instances.</p><h3 id="view-responses"><a href="#view-responses" class="header-anchor">#</a> View Responses</h3><p>If you need access to the <code>Response</code> class methods, but want to return a view as the response content, you may use the <code>Response::view</code> method for convenience:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">view</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::hello&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="json-responses"><a href="#json-responses" class="header-anchor">#</a> JSON Responses</h3><p>The <code>json</code> method will automatically set the <code>Content-Type</code> header to application/json, as well as convert the given array into JSON using the <code>json_encode</code> PHP function:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you would like to create a JSONP response, you may use the <code>json</code> method in addition to <code>setCallback</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CA&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">setCallback</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;callback&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="file-downloads"><a href="#file-downloads" class="header-anchor">#</a> File Downloads</h3><p>The <code>download</code> method may be used to generate a response that forces the user&#39;s browser to download the file at the given path (first argument). The <code>download</code> method optionally accepts a file name (second argument), which will determine the file name that is seen by the user downloading the file, and an array of HTTP headers (third argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">deleteFileAfterSend</span><span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Symfony HttpFoundation, which manages file downloads, requires the file being downloaded to have an ASCII file name.</p></div><h4 id="streamed-downloads"><a href="#streamed-downloads" class="header-anchor">#</a> Streamed Downloads</h4><p>In some cases you may want to convert a string response to a downloadable response without having to write the contents to disk. Use the <code>streamDownload</code> method to solve this, the method accepts a callback (first argument), filename (second argument), and an optional array of headers (third argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">streamDownload</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token string single-quoted-string">&#39;CSV Contents...&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;export.csv&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="file-responses"><a href="#file-responses" class="header-anchor">#</a> File Responses</h3><p>The <code>file</code> method is be used to display a file, such as an image or PDF, directly in the user&#39;s browser instead of initiating a download. This method accepts the path to the file (first argument) and an array of headers (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token variable">$headers</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="redirects"><a href="#redirects" class="header-anchor">#</a> Redirects</h2><p>Redirect responses are typically instances of the <code>Illuminate\\Http\\RedirectResponse</code> class, and contain the proper headers needed to redirect the user to another URL. The simplest way to generate a <code>RedirectResponse</code> instance is to use the <code>to</code> method on the <code>Redirect</code> facade.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="returning-a-redirect-with-flash-data"><a href="#returning-a-redirect-with-flash-data" class="header-anchor">#</a> Returning a Redirect with Flash Data</h3><p>Redirecting to a new URL and <a href="./session.html">flashing data to the session</a> are typically done at the same time. So, for convenience, you may create a <code>RedirectResponse</code> instance and flash data to the session in a single method chain:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user/login&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Login Failed&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Since the <code>with</code> method flashes data to the session, you may retrieve the data using the typical <code>Session::get</code> method.</p></div><h4 id="redirecting-to-the-previous-url"><a href="#redirecting-to-the-previous-url" class="header-anchor">#</a> Redirecting to the Previous URL</h4><p>You may wish to redirect the user to their previous location, for example, after a form submission. You can do so by using the <code>back</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withInput</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="redirecting-to-the-current-page"><a href="#redirecting-to-the-current-page" class="header-anchor">#</a> Redirecting to the Current Page</h4><p>Sometimes you want to simply refresh the current page, you can do this using the <code>refresh</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">refresh</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="response-macros"><a href="#response-macros" class="header-anchor">#</a> Response Macros</h2><p>If you would like to define a custom response that you can re-use in a variety of your routes and controllers, you may use the <code>Response::macro</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">macro</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;caps&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>macro</code> function accepts a name as its first argument, and a Closure as its second. The macro&#39;s Closure will be executed when calling the macro name on the <code>Response</code> class:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">caps</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may define your macros in the <code>boot</code> method of a <a href="./../extending.html">plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place macro registrations.</p><h2 id="views"><a href="#views" class="header-anchor">#</a> Views</h2><p>Views are a great way to store system based presentation logic, such as markup used by an API or end point, or markup that is shared with the CMS and back-end areas. Views are also used by the <a href="./../system/sending-mail.html">Mail service</a> for providing default template content. Views are typically stored in the <code>views</code> directory of a plugin.</p><p>A simple view could look something like this:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.htm --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Views can also be parsed using PHP templating by using the <code>.php</code> extension:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- View stored in plugins/acme/blog/views/greeting.php --&gt;</span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>This view may be returned to the browser using the <code>View::make</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Charlie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first argument is a &quot;path hint&quot; that contains the plugin name, separated by two colons <code>::</code>, followed by the view file name. The second argument passed to <code>View::make</code> is an array of data that should be made available to the view.</p><div class="custom-block tip"><p>The path hint is case sensitive and the plugin name should always be in lowercase.</p></div><h4 id="passing-data-to-views"><a href="#passing-data-to-views" class="header-anchor">#</a> Passing Data to Views</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Using conventional approach</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Using magic methods</span>
<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>In the example above the variable <code>name</code> would be accessible from the view, and would contain <code>Steve</code>. As above, if you want to pass an array of data, you may do so as the second argument given to the <code>make</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>It is also possible to share a piece of data across all views:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Steve&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="passing-a-sub-view-to-a-view"><a href="#passing-a-sub-view-to-a-view" class="header-anchor">#</a> Passing a Sub-view to a View</h4><p>Sometimes you may wish to pass a view into another view. For example, given a sub-view stored at <code>plugins/acme/blog/views/child/view.php</code>, we could pass it to another view like so:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$view</span> <span class="token operator">=</span> <span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::greeting&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nest</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;child&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog::child.view&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The sub-view can then be rendered from the parent view:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> child<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="determining-if-a-view-exists"><a href="#determining-if-a-view-exists" class="header-anchor">#</a> Determining If a View Exists</h4><p>If you need to check if a view exists, use the <code>View::exists</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::mail.customer&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4>`,88)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"./../../cms/features/upload-download.html"},"Uploads & Downloads")]),s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/responses",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel Responses"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const y=c(u,[["render",d]]);export{w as __pageData,y as default};
